/* Bespoke event layer: every campaign slot gets its own historical situation, decisions and advisor response.
   No generic choice-set fallback should be visible when this file is loaded. */

const OATR_EVENT_DETAIL = {
1:{advisor:'sergei',body:['Father Gapon has organized tens of thousands of Petersburg workers around a petition asking for an eight-hour day, higher wages, an end to arbitrary dismissal, and a representative assembly. They are carrying icons and portraits of you because many of them still believe the Tsar is their last court of appeal.','The ministers disagree less about what the workers want than about whether they may be allowed to discover that collective action works. Troops are already being positioned around bridges and squares.'],quote:'“They are coming to you because they still believe in you.”',speaker:'Prince Sviatopolk-Mirsky',choices:[['Receive Gapon and a small workers’ delegation at Tsarskoye Selo. Separate petition from procession and answer it publicly.',{legitimacy:4,reform:2,pressure:-1,flags:['heardGapon']}],['Order the procession halted but announce a royal commission on wages, hours and factory inspection.',{legitimacy:1,reform:1,autocracy:1,pressure:1,flags:['gaponCompromise']}],['Forbid the march from approaching any imperial residence and authorize troops to clear the streets if necessary.',{autocracy:3,blood:4,legitimacy:-4,pressure:3,flags:['bloodySunday']}],['Leave the arrangements to the Interior Ministry and do not return to Petersburg.',{door:3,legitimacy:-3,blood:2,flags:['bloodySunday']}]],advice:'The workers have chosen the oldest language in Russia: they are asking the sovereign to arbitrate against his servants. If you refuse to hear them, they will eventually learn a newer language.'},
2:{advisor:'witte',body:['Petersburg has spent days counting bodies, rumors and strikes. Factories are stopping in sympathy; universities are closing; provincial governors report meetings where portraits of the Tsar are still displayed beside speeches denouncing the government.','At the same time the Japanese war continues to consume money, trains and men. Witte puts the connection plainly: every additional defeat abroad makes every grievance at home harder to contain.'],quote:'“One cannot conduct a colonial war and a domestic revolution with the same treasury.”',speaker:'Sergei Witte',choices:[['Authorize Witte to sound out Japan through neutral intermediaries before Mukden decides the matter for you.',{economy:2,legitimacy:2,pressure:-2,leverage:-2,flags:['earlyPeace1905']}],['Continue the war but replace the most discredited commanders and publish a limited program of domestic concessions.',{military:1,reform:1,legitimacy:1,pressure:1}],['Treat strikes as a security emergency and give governors wider powers of arrest and censorship.',{autocracy:2,blood:2,legitimacy:-2,pressure:2}],['Wait for the military situation to clarify before making any political commitment.',{door:2,pressure:2,legitimacy:-1}]],advice:'Majesty, the dangerous illusion is that foreign war and domestic unrest are separate accounts. They are one ledger and the ink is already running together.'},
3:{advisor:'sergei',body:['Ivan Kalyayev waits outside the Kremlin for Grand Duke Sergei’s carriage. He has already abandoned one attempt because Sergei’s wife and children were with him. This time the carriage is alone.','The bomb explodes at close range. Sergei Alexandrovich is killed instantly. Bits of the carriage strike the monastery wall. Moscow knows before Petersburg does.'],quote:'“The Governor-General is dead.”',speaker:'A telegram from Moscow',choices:[['Oh fuck.',{veil:1,pressure:2,flags:['sergeiKilled']}]],advice:'There is no memorandum for this.'},
4:{advisor:'nicholas',body:['Rozhestvensky’s Baltic Fleet has reached the Tsushima Strait after an eighteen-thousand-mile voyage. Admiral Tōgō crosses its course and destroys the formation in a single day. Most Russian battleships are sunk or captured; thousands of sailors are dead or prisoners.','The Naval Ministry’s first instinct is to blame matériel. The surviving officers blame signals, gunnery, coal, doctrine, ship design, intelligence and one another.'],quote:'“The fleet did not lose a battle. It ceased to exist.”',speaker:'Grand Duke Alexei Alexandrovich',choices:[['Accept Roosevelt’s mediation and end the war before the army is asked to redeem the navy.',{economy:2,legitimacy:1,pressure:-2,flags:['portsmouth']}],['Continue the war on land and demand a victory before negotiations.',{military:1,blood:2,economy:-2,pressure:2}],['Dismiss the naval leadership, publish procurement failures and rebuild around gunnery schools and professional staff work.',{military:3,reform:2,legitimacy:2,autocracy:-1}],['Keep the command intact but fund rapid replacement construction to restore prestige.',{military:1,economy:-3,autocracy:1}]],advice:'The lesson is not that Russia needs more ships. It is that Russia cannot afford institutions where birth and proximity to court outrank the ability to hit a target.'},
5:{advisor:'trepov',body:['On the battleship Potemkin, rotten meat and a threatened firing squad turn a provisioning dispute into mutiny. Officers are killed, the red flag is raised, and the ship sails toward Odessa while the city is already tense with strikes.','The Black Sea command fears contagion more than the single ship. Every order now has to answer the question of whether sailors will obey it.'],quote:'“A mutiny is one ship until another crew decides it is an example.”',speaker:'Vice Admiral Chukhnin',choices:[['Offer amnesty to ratings who surrender the ship and separate them from the men who murdered officers.',{legitimacy:1,blood:-1,military:1}],['Send loyal ships to surround Potemkin but forbid firing unless she opens fire first.',{military:1,autocracy:1,pressure:1}],['Order the mutineers destroyed before Odessa turns the ship into a revolutionary shrine.',{blood:3,autocracy:2,legitimacy:-2}],['Open a naval inquiry into food, discipline and officer abuse while negotiations continue.',{reform:2,military:1,legitimacy:1}]],advice:'Discipline will not survive if every grievance becomes treason, but command will not survive if murder becomes negotiation. The distinction matters.'},
6:{advisor:'witte',body:['Interior Minister Bulygin presents a proposal for an elected Duma that may discuss legislation but cannot enact it, control ministers or determine the budget. Voting is indirect and heavily weighted toward property.','To the court it looks dangerously novel. To liberals it looks deliberately useless. The political question is whether a body created to absorb pressure can survive being visibly powerless.'],quote:'“If you create a parliament for the purpose of proving parliament useless, it may cooperate.”',speaker:'Sergei Witte',choices:[['Make the Duma legislative on ordinary law and budget while reserving war, dynasty and ministers to the Crown.',{reform:3,legitimacy:3,autocracy:-2,leverage:2,flags:['dumaReal']}],['Issue the Bulygin proposal substantially as written.',{reform:1,autocracy:1,legitimacy:-1}],['Promise an assembly but postpone elections until order is restored.',{door:2,legitimacy:-2,pressure:1}],['Abandon the project and restore government by governors and ministries alone.',{autocracy:3,legitimacy:-3,pressure:2}]],advice:'A weak Duma will not remain weak merely because the statute says so. It will either acquire authority or become a public school for contempt.'},
7:{advisor:'witte',body:['At Portsmouth, Witte has extracted terms better than Russia’s battlefield position deserves. Japan receives Korea and southern Sakhalin but no indemnity. Russian prestige is wounded; the treasury is relieved; the army can come home.','The court now has to decide whether peace is to be sold as prudence, temporary humiliation, or betrayal.'],quote:'“I was sent to make peace, not to invent a victory.”',speaker:'Sergei Witte',choices:[['Accept the treaty and publicly praise Witte for ending a war Russia can no longer profitably fight.',{legitimacy:2,economy:2,pressure:-2,flags:['portsmouth']}],['Accept it quietly and minimize the concessions in official statements.',{economy:2,door:1}],['Reject the terms over Sakhalin and continue negotiations under threat of renewed fighting.',{empire:1,blood:1,economy:-1,pressure:1}],['Accept peace but dismiss Witte soon afterward to keep him from converting diplomatic success into political leverage.',{autocracy:2,leverage:-2,legitimacy:-1,flags:['portsmouth']}]],advice:'Peace has bought time. The immediate temptation will be to spend that time proving that nothing else needed to change.'},
8:{advisor:'witte',body:['Railwaymen walk out, then telegraphers, printers, factory workers, clerks and professionals. The October strike spreads not through a single revolutionary command but through networks of local committees and unions. Petersburg can no longer assume orders will be transmitted merely because they are issued.','Witte says the state is approaching a point where repression alone cannot restore normal administration quickly enough.'],quote:'“The strike has done what no party could do: it has made the government feel its own dependence on society.”',speaker:'Sergei Witte',choices:[['Authorize Witte to negotiate a political settlement with zemstvo and liberal leaders immediately.',{reform:2,legitimacy:2,pressure:-1,leverage:2}],['Offer labor protections and an elected Duma but reject ministerial responsibility to parliament.',{reform:1,legitimacy:1,autocracy:1}],['Declare emergency rule in Petersburg and Moscow and restore rail service by military detachments.',{autocracy:2,blood:2,legitimacy:-2,pressure:2}],['Wait several days to see whether the strike exhausts itself before conceding anything constitutional.',{door:2,pressure:2,legitimacy:-1}]],advice:'The government is not facing an army. It is facing the discovery that modern Russia can stop cooperating.'},
9:{advisor:'witte',body:['Witte places the October Manifesto before you: civil liberties, wider suffrage, and the principle that no law shall take effect without Duma approval. Alexandra calls it surrender. Trepov believes order can still be restored by force.','Signing will not create a settled constitution. It will create a promise, and every faction will immediately fight over what that promise means.'],quote:'“You may preserve the words of autocracy, Majesty, or preserve the monarchy. I doubt you can preserve both.”',speaker:'Sergei Witte',choices:[['Sign it and instruct ministers to treat its guarantees as binding law.',{reform:4,legitimacy:4,autocracy:-3,leverage:3,flags:['octoberManifesto','dumaReal']}],['Sign it but retain broad emergency powers and Crown control of ministers.',{reform:2,legitimacy:1,autocracy:1,door:1,flags:['octoberManifesto']}],['Issue only a consultative Duma and refuse a constitutional principle.',{autocracy:3,legitimacy:-3,blood:1}],['Refuse and order Trepov to restore communications before further discussion.',{autocracy:4,blood:3,legitimacy:-4,pressure:3}]],advice:'The signature is not the settlement. The settlement will be whether your government behaves tomorrow as though the signature meant something.'},
10:{advisor:'trepov',body:['In Odessa and other cities, monarchist crowds mobilize against Jews, students, liberals and revolutionaries. The Union of the Russian People and similar organizations present themselves as spontaneous defenders of Throne and Church. Local police often watch, assist, or decide not to notice.','The political advantage is obvious: the streets can be contested by people who love the monarchy. The danger is equally obvious: they may decide they own it.'],quote:'“Majesty, loyal violence remains violence.”',speaker:'Dmitri Trepov',choices:[['Order governors to suppress pogroms and prosecute policemen who cooperate with them.',{legitimacy:3,reform:1,blood:-2,autocracy:-1,flags:['blackHundredsChecked']}],['Allow patriotic societies to organize but forbid armed marches and sectarian attacks.',{autocracy:1,legitimacy:1,blood:-1}],['Use the Black Hundreds as an auxiliary counterweight to revolutionary street organizations.',{autocracy:2,blood:3,legitimacy:-3,flags:['blackHundredsArmed']}],['Let local governors decide according to conditions in each city.',{door:2,blood:2,legitimacy:-2}]],advice:'A crown that hires a mob eventually discovers the mob has opinions about who deserves the crown.'},
11:{advisor:'nicholas',body:['Kronstadt sailors revolt over discipline, pay, food and the broader political crisis. The naval base outside the capital contains arsenals, forts and thousands of armed men. Loyal troops can retake it, but the fleet is already humiliated by Tsushima and Potemkin.','The question is whether this is treated as mutiny alone or as evidence that the service itself requires reconstruction.'],quote:'“You may shoot a mutiny. You cannot shoot a personnel system.”',speaker:'Grand Duke Nicholas Nikolaevich',choices:[['Retake Kronstadt, then establish a naval commission with authority over pay, discipline and officer promotion.',{military:2,reform:1,blood:1}],['Negotiate surrender with limited amnesty for ratings not implicated in murder or sabotage.',{legitimacy:1,blood:-1,military:1}],['Storm the base immediately and make exemplary sentences public.',{blood:3,autocracy:2,legitimacy:-2}],['Replace only the local command and declare the matter closed.',{military:0,door:1,pressure:1}]],advice:'The fleet has now produced mutiny in two seas. If the answer is always that individual sailors are defective, eventually the arithmetic becomes embarrassing.'},
12:{advisor:'trepov',body:['In Moscow’s Presnya district, armed workers and revolutionary militias erect barricades and exchange fire with troops. The uprising is poorly coordinated but symbolically enormous: one of the empire’s great cities contains neighborhoods where government writ is contested street by street.','Artillery can break the barricades. The political cost depends on whether the government appears to be ending insurrection or punishing a city.'],quote:'“The barricade is a military object. The people behind it are a political problem.”',speaker:'Dmitri Trepov',choices:[['Use troops to clear armed positions but prohibit indiscriminate shelling and follow with arrests based on identified participation.',{blood:1,autocracy:1,legitimacy:0}],['Offer a short surrender deadline and amnesty for those who disarm before assaulting remaining positions.',{legitimacy:1,blood:-1,pressure:-1}],['Use artillery aggressively and end the uprising before Christmas.',{blood:4,autocracy:2,legitimacy:-3}],['Withdraw troops from some districts and let municipal leaders negotiate the barricades down.',{autocracy:-1,legitimacy:1,pressure:1}]],advice:'Moscow will remember not only that the uprising failed, but how the government chose to make it fail.'},
13:{advisor:'witte',body:['The Fundamental Laws are being drafted before the first Duma meets. They can define the October promises as the beginning of constitutional monarchy, or restate autocracy so broadly that the Duma begins life already deceived.','The most contested clauses concern ministerial responsibility, the Crown’s decree power when the Duma is not sitting, and control of foreign policy and the armed forces.'],quote:'“A constitution written to preserve every exception is only a catalog of future quarrels.”',speaker:'Sergei Witte',choices:[['Limit emergency decree power and require ministers to answer formally before the Duma while remaining appointed by the Crown.',{reform:3,legitimacy:3,autocracy:-2,flags:['constitutionalCompact']}],['Keep Crown appointment of ministers and broad Article 87 decree authority but honor legislative consent on ordinary law.',{reform:1,autocracy:1,legitimacy:1}],['Restate the Emperor as autocratic and reduce the October promises to consultative procedure.',{autocracy:3,legitimacy:-3,flags:['fundamentalLawsHard']}],['Delay publication until after seeing what kind of Duma is elected.',{door:2,legitimacy:-1}]],advice:'This document will determine whether future conflict occurs inside rules or over whether the rules exist.'},
14:{advisor:'witte',body:['The First Duma arrives at the Tauride Palace full of Kadets, Trudoviks and men who believe the revolution has forced the monarchy to bargain. Its address to the throne demands land reform, amnesty and responsible government.','Court circles expected a chamber grateful merely to exist. Instead it is behaving like an institution that believes the country sent it to govern.'],quote:'“Majesty, the first parliament is rarely modest. It has spent its whole life waiting to be born.”',speaker:'Sergei Witte',choices:[['Invite leading moderates to negotiate a legislative program on land, local government and civil rights.',{reform:3,legitimacy:3,autocracy:-2,leverage:2,flags:['dumaCoalition']}],['Work issue by issue while refusing any principle of parliamentary ministry.',{reform:1,legitimacy:1,autocracy:1}],['Reject its address publicly and warn that the Crown will dissolve a chamber that exceeds its competence.',{autocracy:2,legitimacy:-2,pressure:1}],['Ignore the address and transact business only through ministers.',{door:2,legitimacy:-2}]],advice:'The question is not whether these deputies are irritating. It is whether you want irritating men arguing in the Tauride Palace or organizing outside it.'},
15:{advisor:'stolypin',body:['The First Duma refuses to moderate its land demands, while ministers refuse to accept compulsory expropriation. The chamber has become a theater of mutual delegitimization.','Dissolution is constitutionally available, but the manner of dissolution will teach everyone what elections mean under the new order.'],quote:'“A parliament may be dissolved without teaching the country that parliament itself is fraudulent.”',speaker:'Pyotr Stolypin',choices:[['Dissolve it, call new elections promptly, and publish a specific government land program before the campaign.',{autocracy:1,reform:1,land:2,legitimacy:1}],['Keep it sitting and force ministers to negotiate a narrower land bill.',{reform:2,land:2,autocracy:-1,pressure:1}],['Dissolve it and prosecute deputies who encourage resistance to taxes or conscription.',{autocracy:3,blood:1,legitimacy:-3,flags:['dumaBroken']}],['Suspend the session indefinitely without setting an election date.',{door:2,legitimacy:-3,autocracy:1}]],advice:'Dissolution can be procedure or revenge. Russia will notice which one you choose.'},
16:{advisor:'stolypin',body:['A Socialist Revolutionary bombing destroys part of Stolypin’s dacha on Aptekarsky Island during his public reception. Dozens are killed or wounded; two of Stolypin’s children are badly injured. Stolypin himself walks out and continues giving orders.','He asks for field courts-martial to process terrorist cases quickly, but also insists that repression without reform will only refill the underground.'],quote:'“First calm, then reform. But reform, Majesty—not merely calm.”',speaker:'Pyotr Stolypin',choices:[['Approve temporary field courts with a fixed sunset and simultaneously accelerate land legislation.',{autocracy:1,blood:1,land:2,reform:1}],['Reject extraordinary courts and strengthen ordinary prosecutors, police intelligence and witness protection.',{reform:2,legitimacy:2,blood:-1}],['Give Stolypin broad emergency powers without a sunset.',{autocracy:3,blood:3,legitimacy:-2}],['Remove Stolypin from the line of fire and seek a less polarizing minister.',{door:1,leverage:-2,legitimacy:-1,flags:['stolypinChecked']}]],advice:'Terrorism is trying to force the state to choose between panic and paralysis. The useful answer is neither.'},
17:{advisor:'stolypin',body:['Stolypin proposes allowing peasants to leave the village commune and consolidate strips into privately owned farms. The Peasant Land Bank would help purchases. The wager is social as much as economic: create proprietors with something to lose before revolutionary land seizure becomes irresistible.','Landlords fear a permanent shift in rural power; communalists fear creating a rural class divide; officials fear the paperwork.'],quote:'“Give the peasant a stake in order that is his, not merely yours.”',speaker:'Pyotr Stolypin',choices:[['Issue the decree and fund consolidation, surveying and Peasant Bank credit at scale.',{land:4,reform:2,economy:1,autocracy:-1,flags:['stolypinLand']}],['Permit exit from the commune but move slowly on credit and consolidation.',{land:2,reform:1}],['Protect the commune as the basis of Russian social stability.',{autocracy:1,land:-2,legitimacy:-1}],['Let governors decide province by province.',{door:1,land:1,legitimacy:0}]],advice:'This is the rare reform that changes daily life without asking the peasant to love constitutional theory. That is why it frightens both radicals and courtiers.'},
18:{advisor:'stolypin',body:['The Second Duma is more radical and more fragmented than the first. Social Democrats, Socialist Revolutionaries, Kadets, national parties and rightists use the chamber as both legislature and propaganda stage.','The government uncovers alleged revolutionary links among Social Democratic deputies. Stolypin can prosecute specific men, or use the scandal to alter the entire electoral order.'],quote:'“A bad Duma is an argument for better politics, not necessarily for worse arithmetic.”',speaker:'Pyotr Stolypin',choices:[['Prosecute deputies only on documented criminal evidence and leave the electoral law intact.',{reform:2,legitimacy:2,autocracy:-1}],['Dissolve the Duma but keep the franchise and call elections quickly.',{autocracy:1,legitimacy:0}],['Dissolve it and revise the franchise toward property owners and Russian provinces.',{autocracy:3,reform:-1,legitimacy:-2,flags:['juneThird']}],['Keep the Duma sitting while isolating revolutionary factions through agreements with Octobrists and Kadets.',{reform:2,leverage:1,pressure:1}]],advice:'You can rig the electorate and obtain quieter deputies. You cannot rig society with the same ease.'},
19:{advisor:'stolypin',body:['After the June Third changes, the new electoral law gives far more weight to landlords, property owners and Russian heartland voters. The Third Duma is consequently more conservative and more workable.','This is a chance either to create a durable legislative coalition or to treat the chamber’s obedience as proof that politics can be safely ignored.'],quote:'“A tame parliament is useful only if one remembers it is still a parliament.”',speaker:'Pyotr Stolypin',choices:[['Build an Octobrist government bloc and let the Duma own part of the reform program.',{reform:2,legitimacy:2,leverage:2,flags:['octobristBloc']}],['Use the stable Duma to pass government bills while keeping ministers insulated from party politics.',{reform:1,autocracy:1,economy:1}],['Treat the electoral law as the final constitutional settlement and narrow further concessions.',{autocracy:2,legitimacy:-1}],['Bypass the chamber with Article 87 whenever it becomes inconvenient.',{door:1,autocracy:2,legitimacy:-2}]],advice:'The state finally has a legislature it can work with. It would be a remarkable mistake to conclude that this proves cooperation unnecessary.'},
20:{advisor:'kokovtsov',body:['The Finance Ministry presents the first genuinely hopeful postwar figures. Railway revenues are recovering, foreign borrowing remains possible, and industrial orders are rising. But debt service, military reconstruction and land reform are competing for the same rubles.','Kokovtsov asks for priorities rather than another promise that everything is essential.'],quote:'“The budget cannot distinguish patriotic necessities from expensive habits.”',speaker:'Vladimir Kokovtsov',choices:[['Prioritize railways, schools, electrification and industrial credit; stretch military rebuilding over several years.',{economy:4,reform:1,military:-1}],['Split new revenue between military modernization and productive infrastructure.',{economy:2,military:2}],['Make rearmament first claim on new revenue and defer civilian investment.',{military:3,economy:-1,autocracy:1}],['Protect noble tax privileges and finance expansion through additional foreign borrowing.',{economy:0,autocracy:1,door:1}]],advice:'Russia can become richer and safer. It cannot become both instantly, and pretending otherwise only chooses debt as the deciding minister.'},
21:{advisor:'stolypin',body:['Reports from Tambov and neighboring provinces show peasants leaving communes, consolidating allotments and borrowing through the Peasant Land Bank. The results are uneven: some new farmers prosper, others sell out and migrate.','The reform now needs cadastral surveys, agronomists, rural credit and legal courts capable of resolving ownership disputes without bribery.'],quote:'“A decree can open a gate. It cannot plow the field.”',speaker:'Pyotr Stolypin',choices:[['Fund surveyors, agronomy stations, rural courts and Peasant Bank credit as one integrated program.',{land:4,economy:2,reform:1}],['Concentrate resources on the most promising grain provinces first.',{land:3,economy:1}],['Slow consolidation where communal elders and landlords object.',{land:1,autocracy:1,legitimacy:-1}],['Shift emphasis from ownership to resettlement in Siberia.',{land:2,empire:1,economy:1}]],advice:'The reform will be judged by whether ordinary men can make ownership work after the manifesto and speeches are forgotten.'},
22:{advisor:'stolypin',body:['Stolypin asks for something more dangerous than a statute: sustained political protection. His enemies at court call him arrogant; landlords call him a revolutionary in uniform; radicals call him a hangman.','He wants twenty years without a major foreign war, continuity in office, and authority to force ministries to cooperate on land, local government and education.'],quote:'“Give the state twenty years of peace, internal and external, and you will not recognize Russia.”',speaker:'Pyotr Stolypin',choices:[['Publicly identify the Crown with his program and make obstruction by court factions an act of disobedience to you.',{reform:3,land:3,legitimacy:2,autocracy:-2,leverage:3,flags:['stolypinBacked']}],['Back land and economic reform but keep constitutional and nationality questions under your own control.',{land:3,economy:2,reform:1,autocracy:1,flags:['stolypinEconomicOnly']}],['Support him only while he commands a Duma majority; do not spend dynastic prestige on his personal survival.',{reform:1,land:2,leverage:-1}],['Begin looking for a quieter chairman of the Council of Ministers.',{autocracy:2,door:1,leverage:-3,flags:['stolypinChecked']}]],advice:'Majesty, reform without a patron at the top will be eaten by the interests it threatens. If I am to be that patron, I need to know you will not apologize for me next week.'},
23:{advisor:'stolypin',body:['The Finnish constitutional conflict returns. Petersburg officials argue that imperial defense, customs and certain laws must override Finland’s Diet. Finnish politicians insist the old constitutional relationship limits unilateral Russian legislation.','The choice is not independence versus empire. It is what kind of empire Finland is actually in.'],quote:'“Uniformity is administratively elegant and politically expensive.”',speaker:'Pyotr Stolypin',choices:[['Recognize Finnish control over internal law while reserving defense, foreign affairs and customs to the empire.',{empire:3,reform:2,legitimacy:2,autocracy:-1,flags:['federalFinland']}],['Keep autonomy in culture and local administration but assert imperial legislative supremacy.',{empire:2,autocracy:1}],['Russify administration and restrict the Finnish Diet’s obstruction of imperial law.',{autocracy:2,empire:1,legitimacy:-2}],['Postpone the dispute and negotiate only specific military obligations.',{door:1,empire:1}]],advice:'Finland is testing whether loyalty must mean sameness. The answer you give there will be heard in Warsaw and Tiflis.'},
24:{advisor:'lamsdorff',body:['Austria-Hungary formally annexes Bosnia-Herzegovina, which it has occupied since 1878. Serbia erupts in fury. Russia is weakened by war and revolution, yet public opinion expects the government to defend Slavic interests.','Foreign Minister Izvolsky claims Vienna violated the understanding he thought he had reached over the Straits. Germany backs Austria firmly.'],quote:'“We have been presented with a humiliation carefully wrapped as a legal fact.”',speaker:'Alexander Izvolsky',choices:[['Accept the annexation for now and concentrate on rebuilding Russian power.',{economy:1,military:1,empire:-1,pressure:-1,flags:['germanAccommodation']}],['Demand international compensation for Serbia and a conference on the annexation.',{empire:1,legitimacy:1,pressure:1}],['Back Serbia diplomatically and begin limited military preparations despite Russian weakness.',{empire:2,military:1,economy:-1,pressure:2}],['Seek a broader understanding with Berlin in exchange for recognizing the annexation.',{empire:0,britain:1,flags:['germanophile']}]],advice:'Russia cannot prevent every unfavorable fact today. The real question is whether accepting one buys strength or merely teaches Vienna that we will accept the next.'},
25:{advisor:'lamsdorff',body:['Belgrade newspapers call for war and volunteers drill in the streets. Serbian ministers privately ask what Russia will actually do if Austria presses further.','A vague promise may deter Vienna—or encourage Serbia to take risks in the belief that Russian armies are already committed.'],quote:'“The most dangerous guarantee is the one both sides interpret differently.”',speaker:'Foreign Ministry memorandum',choices:[['Tell Serbia explicitly that Russia will support diplomacy and reform, not a Serbian war over Bosnia.',{pressure:-1,empire:-1,legitimacy:1,flags:['serbiaLimited']}],['Promise political support but no military commitment.',{empire:1}],['Assure Belgrade that Russian prestige is bound to Serbia’s survival and territorial claims.',{empire:2,pressure:2,flags:['serbiaEntangled']}],['Use the crisis to open direct talks with Berlin on a Russian-German Balkan modus vivendi.',{flags:['germanophile'],britain:1,pressure:-1}]],advice:'Serbia needs to know whether Russia is an ally, a patron, or an audience. Ambiguity is flattering until artillery begins.'},
26:{advisor:'nicholas',body:['The General Staff presents its post-Mukden reforms: new corps organization, artillery doctrine, mobilization districts, staff education and procurement standards. The proposals threaten old Guard privileges and patronage networks.','The army can become more professional, but professionalism means officers being promoted for competence instead of genealogy and regiments being supplied by systems instead of favors.'],quote:'“The Japanese did not defeat our courage. They defeated our arrangements.”',speaker:'General Palitsyn',choices:[['Adopt competitive staff promotion, standardized procurement and realistic field exercises across the army.',{military:4,reform:2,economy:-1,flags:['armyProfessional']}],['Modernize artillery and logistics but protect Guard promotion customs.',{military:2,autocracy:1,economy:-1}],['Expand formations and reserves first; doctrine can follow mass.',{military:1,economy:-2,autocracy:1}],['Create an inspectorate reporting directly to you to supervise reform.',{military:2,autocracy:2,door:1}]],advice:'The army does not need to become less Russian. It needs to become less surprised by mathematics.'},
27:{advisor:'alexandra',body:['Bishops and theologians petition for restoration of a Church council and some relief from control by the Holy Synod’s lay Procurator. The paradox is old: Orthodoxy is the empire’s privileged faith, yet its hierarchy is administered through a state bureaucracy.','Liberating the Church from ministries could strengthen faith while weakening one of the Crown’s traditional instruments.'],quote:'“A Church governed as a department will eventually learn the habits of a department.”',speaker:'Metropolitan Antony',choices:[['Authorize preparations for a national council and reduce the Procurator’s administrative control.',{faith:4,reform:2,legitimacy:2,autocracy:-1,flags:['churchFree']}],['Give bishops wider internal authority but retain the Synod and Procurator.',{faith:2,autocracy:1}],['Keep the Petrine system unchanged as a safeguard against clerical politics.',{autocracy:2,faith:-1}],['Allow limited reform only in seminaries, missions and parish administration.',{faith:1,reform:1}]],advice:'Nicky, if the Church is truly holy it should not require a civil servant to make it so. But you must be certain its freedom will not become another parliament.'},
28:{advisor:'kokovtsov',body:['Baku’s oil fields combine extraordinary wealth with miserable labor conditions, ethnic rivalry and revolutionary organization. Armenian, Azeri and Russian workers live beside firms tied to international capital and local magnates.','A strike can become a wage dispute, a nationalist riot or a revolutionary uprising depending on which grievance catches first.'],quote:'“Baku produces oil faster than the administration produces legitimacy.”',speaker:'Finance Ministry inspector',choices:[['Create binding industrial arbitration, safety rules and elected worker insurance boards for the oil fields.',{reform:3,legitimacy:2,economy:1}],['Broker a settlement through employers and local notables while expanding police intelligence.',{economy:1,autocracy:1,legitimacy:1}],['Militarize the oil district and criminalize strike committees that interrupt production.',{autocracy:2,blood:2,economy:1,legitimacy:-2}],['Give Armenian and Muslim municipal elites greater control over local services and policing.',{empire:2,legitimacy:2,reform:1}]],advice:'If Baku is governed only as a fuel depot, everyone living there will eventually treat the empire as merely the owner of the depot.'},
29:{advisor:'stolypin',body:['In Kiev and the western provinces, arguments over schooling, Polish influence, Ukrainian-language publishing and Orthodox institutions are becoming proxies for the larger question of national identity.','Officials can promote Russian culture, suppress competitors, or accept that imperial loyalty may coexist with multiple languages.'],quote:'“A language becomes more political when policemen begin correcting grammar.”',speaker:'A zemstvo delegate',choices:[['Permit Ukrainian and Polish cultural associations and schooling under loyalty and curriculum requirements.',{empire:3,legitimacy:2,reform:1}],['Fund Russian schools heavily but do not prohibit private minority-language education.',{empire:2,autocracy:1}],['Restrict Ukrainian publishing and strengthen Russian-language requirements in public institutions.',{autocracy:2,empire:1,legitimacy:-2}],['Leave cultural policy to governors and avoid an empire-wide rule.',{door:1,empire:0}]],advice:'The state can make Russian culture attractive or compulsory. It should not confuse the two.'},
30:{advisor:'kokovtsov',body:['The Council of Ministers has discovered that railway policy, industrial finance, peasant resettlement and military procurement are being managed by overlapping departments with contradictory authority. Files circulate for months because no ministry wants responsibility without control.','The bureaucratic problem is not lack of officials. It is that Russia has built vertical chains which meet only at the Tsar.'],quote:'“Every ministry is perfectly organized until it must cooperate with another ministry.”',speaker:'Vladimir Kokovtsov',choices:[['Create a permanent interministerial secretariat under the Council chairman with authority to resolve jurisdictional conflicts.',{reform:2,economy:2,door:-2}],['Clarify statutes but keep ministries responsible directly to the Crown.',{autocracy:1,economy:1}],['Centralize disputed portfolios in the Imperial Chancellery.',{autocracy:3,door:1}],['Commission another administrative review before changing responsibilities.',{door:3,economy:-1}]],advice:'Majesty, if every disagreement climbs to your desk, the empire is not centralized. It is bottlenecked.'},
31:{advisor:'stolypin',body:['Stolypin wants elected zemstvos in the western provinces. Russian conservatives fear Polish landlords will dominate them; Polish elites fear rules designed to manufacture Russian majorities.','The proposal is a test of whether local self-government can be extended without turning every district boundary into a national struggle.'],quote:'“One cannot teach responsibility locally while arranging representation nationally like a police operation.”',speaker:'Pyotr Stolypin',choices:[['Create zemstvos with broad local powers and franchise rules not explicitly based on nationality.',{reform:3,empire:2,legitimacy:2}],['Create them but reserve quotas and safeguards for Russian landowners.',{reform:1,empire:1,autocracy:1}],['Drop the bill rather than hand local government to Polish interests.',{autocracy:2,empire:-1,legitimacy:-1}],['Use the dispute to negotiate a wider federal bargain with Polish moderates.',{reform:2,empire:3,flags:['federalPoland']}]],advice:'If every local institution must be designed to guarantee the correct nationality wins, it is not self-government. It is a census with chairs.'},
32:{advisor:'rasputin',body:['Alexei suffers another severe bleeding episode. The doctors cannot stop it. Alexandra sends for Grigori Rasputin, the Siberian pilgrim she believes can calm the boy. His presence or telegram coincides with improvement often enough that the family’s trust deepens.','Ministers know only fragments of the illness. The court knows enough to gossip. The question is how far a private source of hope will be allowed into public life.'],quote:'“Do not let the doctors bother him. The little one will not die.”',speaker:'Grigori Rasputin',choices:[['Allow Rasputin access to the family but explicitly bar him from recommendations on appointments or policy.',{veil:1,faith:1,legitimacy:1,flags:['rasputinLimited']}],['Keep him as a private spiritual adviser and conceal the relationship from political society.',{veil:2,door:1}],['Treat his apparent help to Alexei as evidence that his judgment deserves broader trust.',{veil:4,legitimacy:-1,flags:['rasputinTrusted']}],['Send him away once Alexei recovers and forbid further court access.',{veil:-2,faith:-1,legitimacy:1,flags:['rasputinBanish']}]],advice:'Papa, they understand blood only when it is on a battlefield. They do not understand a child bleeding into his own skin. Let them laugh.'},
33:{advisor:'stolypin',body:['Stolypin’s relationship with the Third Duma and the court is deteriorating. He wants to use Article 87 to create western zemstvos after the State Council blocks him, and he threatens resignation unless allowed to proceed.','His enemies believe he has become indispensable in his own mind. His allies fear that if the Crown humiliates him publicly, the reform coalition will conclude that court intrigue outranks policy.'],quote:'“If the government cannot govern when its policy is unpopular at court, then the court is the government.”',speaker:'Pyotr Stolypin',choices:[['Back Stolypin against the State Council and force the western zemstvo measure through.',{reform:3,leverage:2,autocracy:-1,flags:['stolypinBacked']}],['Require him to compromise with the State Council rather than use emergency procedure.',{reform:1,autocracy:1}],['Accept his resignation threat and begin replacing his network.',{autocracy:2,leverage:-3,flags:['stolypinChecked']}],['Support the measure but privately rebuke Stolypin for threatening the sovereign.',{reform:2,door:1,leverage:-1}]],advice:'I can survive enemies. I cannot build a program if every courtier knows that opposing me is safer than opposing you.'},
34:{advisor:'trepov',body:['Nicholas attends celebrations in Kiev. Stolypin has received threats, yet security around the opera house is fragmented among police, gendarmes and local officials. Dmitry Bogrov, an Okhrana informant with revolutionary ties, possesses access that should alarm anyone who compares the files.','The security apparatus insists the arrangements are adequate. The files themselves say otherwise.'],quote:'“The theatre is secure.”',speaker:'Kiev security memorandum',choices:[['Remove Bogrov’s access, reorganize the detail under one commander and treat threats to Stolypin as credible.',{blood:-1,reform:1,flags:['stolypinProtected']}],['Add guards around the imperial box but leave Stolypin’s arrangements to local police.',{autocracy:1,flags:['stolypinExposed']}],['Proceed unchanged; visible overreaction would reward terrorists.',{door:2,flags:['stolypinExposed']}],['Order a broader purge of double agents from the Kiev Okhrana before the visit.',{reform:1,blood:1,flags:['okhranaReformed','stolypinProtected']}]],advice:'Security services become dangerous when they know so much that no one can tell which dangers they are observing and which they are cultivating.'},
35:{advisor:'kokovtsov',body:['At the Kiev opera, Bogrov approaches Stolypin during an interval and shoots him. Stolypin crosses himself toward the Tsar before collapsing. Whether he survives depends on the precautions already taken and the speed of treatment.','The political problem begins immediately: his program spans ministries, banks, governors and Duma alliances, but much of its authority still rests on the man himself.'],quote:'“I am happy to die for the Tsar.”',speaker:'Pyotr Stolypin',choices:[['If he lives, keep him in office with explicit authority to finish land and administrative reform; if he dies, preserve his program intact.',{reform:3,land:3,legitimacy:1,flags:['stolypinProgramContinues']}],['Shift leadership to Kokovtsov and preserve economic reform while cooling political confrontation.',{economy:2,land:2,reform:1}],['Use the assassination to expand police powers and suspend controversial reforms.',{autocracy:2,blood:2,reform:-2}],['Treat Stolypin’s system as too personalized and return power to separate ministries.',{door:2,reform:-1}]],advice:'The state will reveal whether Stolypin built institutions or merely held several institutions together by force of personality.'},
36:{advisor:'kokovtsov',body:['Kokovtsov inherits a government exhausted by Stolypin’s confrontations. He is financially competent, politically cautious and far less interested in forcing the nobility or Duma into grand settlements.','Growth continues. That is precisely the danger: prosperity can make unresolved constitutional questions look safely theoretical.'],quote:'“I can balance the budget, Majesty. I cannot balance every grievance in Russia.”',speaker:'Vladimir Kokovtsov',choices:[['Charge Kokovtsov with preserving Stolypin’s land, education and administrative program despite his caution.',{economy:3,land:2,reform:1}],['Let the government concentrate on growth and stop provoking the court with constitutional experiments.',{economy:3,autocracy:1,leverage:-1}],['Use the transition to restore stronger direct palace control over ministries.',{autocracy:3,door:1,reform:-1}],['Seek a new political premier capable of rebuilding a Duma coalition.',{reform:2,legitimacy:1,pressure:1}]],advice:'Economic growth is a blessing, Majesty. It is also the most pleasant possible excuse for postponing politics.'},
37:{advisor:'sazonov',body:['Russian forces and diplomats press Persia while Britain protects its own sphere under the Anglo-Russian Convention. The Persian constitutional government is weak, foreign loans are decisive, and Russian troops can enforce demands with little immediate military risk.','What Russia does in Persia will reveal whether modernization at home has changed imperial behavior abroad.'],quote:'“A weak neighbor is not the same thing as an empty country.”',speaker:'Sergei Sazonov',choices:[['Limit intervention to border security and financial guarantees; withdraw troops as soon as terms are met.',{empire:1,legitimacy:1,blood:-1}],['Maintain a northern sphere through loans, consuls and advisers rather than permanent occupation.',{empire:2,economy:1}],['Use military pressure to install reliably pro-Russian authorities in the north.',{empire:3,autocracy:1,blood:1}],['Coordinate tightly with Britain and divide responsibilities under the existing convention.',{empire:1,britain:-1,flags:['ententeCooperation']}]],advice:'Persia is inexpensive to coerce. That is exactly why it is a useful test of whether Russia knows what power is for.'},
38:{advisor:'alexandra',body:['The empire ends 1911 richer and calmer than it began 1905. The railways run, harvests improve, factories expand and the Duma has become routine enough to be boring. Yet the dynasty remains suspicious of the very institutions that helped create the calm.','At Tsarskoye Selo, the family feels insulated from the political world. Alexandra increasingly believes that distance from Petersburg society is a form of moral clarity.'],quote:'“Nicky, peace is proof that you did not betray what Papa left you.”',speaker:'Alexandra Feodorovna',choices:[['Use the calm to regularize constitutional practice and make extraordinary powers rarer.',{reform:2,legitimacy:2,door:-1}],['Preserve the current balance without further experiments.',{economy:1,autocracy:1}],['Conclude that the crisis has passed and restore more initiative to the palace.',{autocracy:2,door:1}],['Spend the political capital on federal and church questions while conditions are quiet.',{empire:2,faith:2,reform:1}]],advice:'Peace can mean the system is healing. It can also mean the cracks have stopped moving for the moment. Do not let courtiers decide which interpretation comforts you most.'},
39:{advisor:'kokovtsov',body:['At the Lena goldfields in Siberia, workers strike over food, hours and company practices. Troops fire on a crowd; hundreds are killed or wounded. The phrase “So it was, so it will be” spreads after a minister appears to defend the shootings.','The massacre revives labor militancy that had been ebbing since 1905 and gives radicals a fresh symbol unconnected to the old revolution.'],quote:'“So it was, so it will be.”',speaker:'Interior Minister Makarov, disastrously',choices:[['Dismiss officials responsible, prosecute unlawful firing and create an independent mining labor inspection.',{legitimacy:3,reform:2,blood:-2}],['Compensate families and regulate food and contracts without prosecuting officers.',{legitimacy:2,reform:1}],['Defend the troops and warn that illegal strikes cannot dictate state policy.',{autocracy:2,blood:2,legitimacy:-3}],['Order a closed inquiry and prevent publication until unrest subsides.',{door:2,legitimacy:-2}]],advice:'The government has managed to turn a remote labor dispute into a national memory. That is an administrative achievement of the worst kind.'},
40:{advisor:'alexandra',body:['Petersburg newspapers and salons now print Rasputin’s name openly. Stories mix genuine drunkenness and sexual scandal with inventions, political insinuation and attacks on Alexandra’s German birth.','Suppressing the press may enlarge the scandal. Ignoring it may allow the idea that court appointments are being made by a Siberian holy man to harden into common knowledge.'],quote:'“They hate him because they hate me, and they hate me because I love you.”',speaker:'Alexandra Feodorovna',choices:[['Publish clear rules barring private courtiers and spiritual advisers from influencing appointments, and enforce them.',{legitimacy:3,veil:-1,reform:1,flags:['rasputinLimited']}],['Ignore personal scandal but remove any official who uses Rasputin’s name as patronage.',{legitimacy:2,veil:0}],['Use censorship and libel prosecutions against newspapers attacking the imperial family.',{autocracy:2,legitimacy:-1,veil:1}],['Let Alexandra continue receiving him and refuse to explain family matters to the public.',{door:1,veil:3,legitimacy:-2,flags:['rasputinTrusted']}]],advice:'Nicky, every concession to gossip teaches them that the private life of the sovereign is theirs to police. But every foolish man who invokes Grigori’s name makes the gossip stronger.'},
41:{advisor:'rasputin',body:['Rasputin has become a permanent feature of the imperial family’s private world. He speaks bluntly about ministers, bishops and war; sometimes his instincts are shrewd, sometimes incoherent.','His most consistent political warning is against a great European war. He believes war will destroy the dynasty whether Russia wins or loses.'],quote:'“If there is war, the whole of Russia will drown in blood.”',speaker:'Grigori Rasputin',choices:[['Keep him away from appointments but listen seriously when he warns against war.',{veil:1,legitimacy:1,flags:['rasputinLimited','rasputinPeace']}],['Allow him to recommend church appointments only, where Alexandra values his judgment.',{veil:2,faith:1,legitimacy:-1}],['Trust him broadly as a counterweight to ministers and court factions.',{veil:4,door:2,legitimacy:-2,flags:['rasputinTrusted']}],['End his access to the palace before scandal becomes constitutional damage.',{veil:-3,legitimacy:2,faith:-1,flags:['rasputinBanish']}]],advice:'The men with uniforms will always tell you there is one more mobilization that will prevent war. The men with papers will always tell you there is one more note. I tell you only: do not go.'},
42:{advisor:'sazonov',body:['Montenegro, Serbia, Bulgaria and Greece attack the Ottoman Empire. Their rapid victories transform the Balkan balance. Russia sympathizes with the Slavs but fears Bulgarian-Serbian disputes, Austrian intervention and a scramble for Constantinople.','The small states are proving capable of changing borders faster than the great powers can agree on rules.'],quote:'“Our clients have discovered that victory makes them less obedient.”',speaker:'Sergei Sazonov',choices:[['Support a negotiated Balkan settlement and refuse automatic backing for any one ally’s territorial maximum.',{empire:1,legitimacy:1,pressure:-1}],['Back Serbia strongly while warning Bulgaria not to challenge Russian leadership.',{empire:2,pressure:1,flags:['serbiaEntangled']}],['Coordinate with Germany and Austria to freeze the conflict before it reaches the Straits.',{pressure:-1,flags:['germanophile']}],['Use Ottoman weakness to press Russian commercial and naval rights at the Straits.',{empire:3,pressure:1}]],advice:'The Balkans are no longer a chessboard where great powers move obedient pieces. The pieces have rifles and their own newspapers.'},
43:{advisor:'nicholas',body:['The General Staff tests mobilization plans against a Balkan crisis and finds an ugly constraint: deployment schemes assume particular enemies, rail priorities and timetables. Partial mobilization against Austria disrupts plans designed for simultaneous war with Germany.','The technical problem is real, but the political danger is allowing mobilization planning to dictate diplomacy.'],quote:'“A plan should answer policy. We are in danger of asking policy to fit the plan.”',speaker:'General Danilov',choices:[['Order a genuinely flexible partial-mobilization plan even if it costs money and readiness in the short term.',{military:3,economy:-2,reform:1,flags:['flexMobilization']}],['Keep the existing general plan and rely on political leaders not to order partial mobilization.',{military:1,door:1}],['Increase rolling stock and reserve depots so multiple plans become practical.',{military:2,economy:-2}],['Give the General Staff wider discretion to begin preparatory measures before formal mobilization.',{military:2,autocracy:1,pressure:1,flags:['armyAutonomy']}]],advice:'The army needs plans that permit the sovereign to choose. Otherwise the plan is sovereign and we are merely its clerks.'},
44:{advisor:'sazonov',body:['The Ottoman defeats revive the oldest temptation in Russian policy: Constantinople and the Straits. Military planners discuss occupation contingencies; diplomats warn that Britain, France, Austria and Germany all have reasons to oppose unilateral Russian control.','The city is simultaneously strategic objective, Orthodox symbol and geopolitical trap.'],quote:'“Every Russian schoolboy knows why we want Constantinople. That does not mean Europe has forgotten why it does not.”',speaker:'Sergei Sazonov',choices:[['Make freedom of passage for Russian commerce the objective and renounce unilateral annexation.',{economy:2,legitimacy:1,empire:0}],['Seek an international Straits regime with Russian naval privileges.',{empire:2,pressure:1}],['Prepare a secret military plan to seize Constantinople during a wider Ottoman collapse.',{military:2,empire:3,veil:1,flags:['constantinoplePlan']}],['Trade Russian restraint at the Straits for a strategic understanding with Germany.',{flags:['germanophile'],pressure:-1,empire:1}]],advice:'The City of Cities can be a policy or a prophecy. The second is more intoxicating and considerably harder to negotiate.'},
45:{advisor:'alexandra',body:['The Romanov dynasty celebrates three hundred years since Michael Romanov’s election in 1613. The imperial family tours old Russian cities amid enormous crowds, icons, banners and carefully staged scenes of continuity between dynasty and people.','The celebrations can be used to sanctify autocracy, to reconcile monarchy with constitutional institutions, or merely to enjoy evidence that the dynasty is still loved.'],quote:'“Three hundred years, Nicky. They came because they love you.”',speaker:'Alexandra Feodorovna',choices:[['Make the jubilee explicitly about dynasty plus Duma, zemstvo and local Russia as one historical state.',{legitimacy:4,reform:1,autocracy:-1}],['Celebrate Orthodoxy, dynasty and national unity without constitutional language.',{legitimacy:2,faith:2,autocracy:1}],['Emphasize uninterrupted autocracy and the sacred duty of obedience.',{autocracy:3,faith:1,legitimacy:0}],['Use the tour to announce pardons and local-government reforms in the dynasty’s name.',{legitimacy:3,reform:2}]],advice:'A jubilee can teach people that the dynasty belongs to their history, or that history belongs to the dynasty. The difference is larger than the banners make it look.'},
46:{advisor:'alexandra',body:['At Kazan Cathedral and across the empire, the tercentenary produces a genuine religious response as well as official ceremony. Pilgrims, peasants, soldiers and townspeople participate on terms not entirely controlled by ministries.','The Church’s public vitality strengthens arguments that it should be less dependent on state administration, not more.'],quote:'“Faith is strongest where the police have the least to do with it.”',speaker:'A parish priest from Yaroslavl',choices:[['Announce that the long-delayed Church Council will finally be convened.',{faith:4,reform:2,legitimacy:2,flags:['churchFree']}],['Expand parish schools and charitable institutions while leaving church government unchanged.',{faith:2,legitimacy:1,economy:-1}],['Use the jubilee to reinforce Orthodoxy’s privileged legal position against sects and converts.',{faith:2,autocracy:2,legitimacy:-1}],['End restrictions on private worship by non-Orthodox Christians while keeping Orthodoxy established.',{faith:1,reform:2,legitimacy:2,flags:['religiousTolerance']}]],advice:'If Orthodoxy is true, it does not need every dissenter fined to prove it.'},
47:{advisor:'kokovtsov',body:['The Azef scandal has become impossible to dismiss. Yevno Azef simultaneously led the Socialist Revolutionary Combat Organization and served as a paid Okhrana informant. He participated in terrorist murders while reporting to the police.','The scandal exposes a system where agents are rewarded for access to conspiracies and therefore have incentives to keep conspiracies alive.'],quote:'“We paid a terrorist to prove there were terrorists.”',speaker:'A furious Justice Ministry official',choices:[['Create judicial oversight of political policing, ban agent provocateurs from organizing crimes and audit informant payments.',{reform:4,legitimacy:3,blood:-1,flags:['okhranaReformed']}],['Keep infiltration but place informants under stricter ministerial supervision.',{reform:1,autocracy:1}],['Expand penetration of revolutionary parties; Azef’s access proves the method works.',{autocracy:2,blood:2,legitimacy:-2}],['Dissolve the existing Okhrana structure and replace it with a conventional security bureau.',{reform:3,pressure:2,flags:['okhranaAbolished']}]],advice:'A secret police that manufactures its own evidence eventually becomes impossible to distinguish from the conspiracy it is paid to uncover.'},
48:{advisor:'sazonov',body:['Warsaw receives the Romanov celebrations with a mixture of official loyalty, Polish nationalism and studied indifference. The Kingdom of Poland remains economically important, politically restless and governed through institutions many Poles regard as imposed.','Moderates offer a bargain: meaningful local autonomy inside the empire in exchange for accepting the Romanov crown and Russian control of defense and foreign affairs.'],quote:'“Poland can be held by garrisons or by interests. Garrisons are more expensive.”',speaker:'Sergei Sazonov',choices:[['Negotiate a Polish Diet with control over education, local law and taxation under the imperial crown.',{empire:4,reform:2,legitimacy:2,flags:['federalPoland']}],['Expand municipal and cultural autonomy without restoring a national legislature.',{empire:2,legitimacy:1}],['Tighten Russian administrative control in anticipation of a European crisis.',{autocracy:2,empire:1,legitimacy:-2}],['Offer autonomy only if Polish parties publicly renounce independence agitation.',{empire:2,autocracy:1,pressure:1}]],advice:'Polish loyalty will never mean forgetting Poland. The useful question is whether that fact must also mean disloyalty to Russia.'},
49:{advisor:'sazonov',body:['The Balkan allies turn on one another. Bulgaria attacks Serbia and Greece; Romania and the Ottoman Empire enter against Bulgaria. The settlement of the First Balkan War collapses almost immediately into a second war.','Russia’s prestige as supposed patron of the Slavic states is damaged by its inability to keep its clients aligned.'],quote:'“We have achieved the rare diplomatic feat of being blamed by every ally at once.”',speaker:'Sergei Sazonov',choices:[['Mediate without choosing a favorite and accept a reduced Russian role in the peninsula.',{pressure:-1,legitimacy:1,empire:-1}],['Side with Serbia as the more strategically valuable partner against Bulgaria.',{empire:2,flags:['serbiaEntangled']}],['Rebuild ties with Bulgaria and restrain Serbia to prevent Austrian encirclement.',{empire:1,pressure:1}],['Coordinate a settlement with Berlin and Vienna, making Balkan stability part of a German-Russian rapprochement.',{flags:['germanophile'],pressure:-1,britain:1}]],advice:'Patronage is not command. The Balkans have now demonstrated that fact twice in twelve months.'},
50:{advisor:'kokovtsov',body:['Putilov and other Petersburg factories see renewed strike organization. Workers are better connected, more literate and more politically experienced than in 1905. Employers fear that concessions will spread; police fear that suppression will do the same.','The industrial boom has created precisely the urban class the old order did not know how to govern.'],quote:'“A modern factory cannot be run forever by rules borrowed from an estate.”',speaker:'Factory inspector report',choices:[['Legalize collective bargaining, workplace committees and accident insurance under enforceable labor law.',{reform:3,legitimacy:3,economy:1}],['Create compulsory state arbitration for major industries and ban political strikes.',{reform:1,autocracy:1,economy:1}],['Allow employers to lock out strikers while police arrest revolutionary organizers.',{autocracy:2,legitimacy:-2,blood:1}],['Use government contracts to force Putilov management to improve wages and conditions without general legislation.',{legitimacy:1,economy:0,door:1}]],advice:'Industrial Russia now has workers who know that the factory stops when they stop. The law must decide what that knowledge becomes.'},
51:{advisor:'kokovtsov',body:['Another cabinet reorganization is proposed because responsibilities for industry, transport, agriculture and internal security overlap. The court habit of moving individual portfolios around has created ministries whose boundaries reflect past crises rather than current tasks.','This is an opportunity to build a cabinet that behaves like a government instead of an imperial inbox.'],quote:'“A ministry should know what it owns before it asks for another building.”',speaker:'Vladimir Kokovtsov',choices:[['Give the Council chairman authority to set cabinet agendas, coordinate budgets and resolve interministerial disputes.',{reform:2,door:-2,economy:2,flags:['cabinetGovernment']}],['Merge overlapping economic departments but keep political ministries directly answerable to you.',{economy:2,autocracy:1}],['Reduce the chairman’s role and require major ministries to report separately to the Crown.',{autocracy:3,door:2}],['Leave the structure alone; constant reorganization is itself becoming disruptive.',{door:1,economy:1}]],advice:'Majesty, there is a point where personal supervision stops being control and becomes the reason no one else can control anything.'},
52:{advisor:'rasputin',body:['Alexei’s illness worsens again, and Alexandra’s reliance on Rasputin becomes more absolute. He is no longer merely a comfort; he is part of the family’s understanding of why the heir is alive.','The secrecy around hemophilia means critics see influence without seeing the private catastrophe that created it.'],quote:'“When the boy suffers, all your ministers become very small.”',speaker:'Grigori Rasputin',choices:[['Tell senior ministers the heir’s diagnosis under secrecy so they understand why Rasputin has private access.',{legitimacy:2,veil:-1,door:-1,flags:['alexeiDisclosed']}],['Keep the illness secret but enforce the boundary between family access and state patronage.',{veil:1,legitimacy:1,flags:['rasputinLimited']}],['Allow Alexandra and Rasputin broad say over church and court appointments while the boy remains ill.',{veil:4,door:2,legitimacy:-2,flags:['rasputinTrusted']}],['Send Rasputin away despite Alexandra’s objections.',{veil:-3,faith:-1,door:1,legitimacy:1}]],advice:'You hide the wound and then wonder why men invent explanations for the bandages.'},
53:{advisor:'nicholas',body:['The General Staff’s 1914 planning assumes that if war comes with Austria, Germany may join quickly. Deployment priorities, fortress policy, artillery ammunition and reserve schedules are all being fixed now.','French planners press Russia to attack Germany early in any war to relieve pressure in the west; Russian officers warn that premature offensives could sacrifice readiness for alliance politics.'],quote:'“An alliance should influence strategy, not replace it.”',speaker:'Grand Duke Nicholas Nikolaevich',choices:[['Build stocks and plans around a slower concentration, refusing an early offensive until armies are ready.',{military:3,economy:-2,legitimacy:1}],['Promise France an early East Prussian offensive and fund the rail capacity to make it less reckless.',{military:2,economy:-3,flags:['frenchCommitment']}],['Prioritize Austria as the first enemy and keep only covering forces against Germany initially.',{military:1,empire:1,pressure:1}],['Give field commanders latitude to adapt concentration after mobilization begins.',{military:2,flags:['armyAutonomy']}]],advice:'A timetable can make an army punctual. It cannot make an impossible offensive wise.'},
54:{advisor:'sazonov',body:['France expects Russia to honor the alliance if Germany attacks, and French loans have helped finance Russian railways and industry. At the same time some court and diplomatic circles still imagine a continental understanding with Berlin.','The empire cannot indefinitely behave as though both alignments are equally available. Credit, military planning and Balkan policy are already choosing for you.'],quote:'“Alliances are most dangerous when a government treats them as insurance policies whose clauses need not be read.”',speaker:'Sergei Sazonov',choices:[['Reaffirm the French alliance but define that Russian mobilization requires a clear German or Austrian act.',{legitimacy:1,pressure:-1,flags:['ententeAligned']}],['Deepen military coordination with France and accept reciprocal offensive obligations.',{military:2,pressure:1,flags:['frenchCommitment','ententeAligned']}],['Open formal talks with Berlin on replacing bloc politics with a Russian-German understanding.',{flags:['germanophile'],britain:1,pressure:-1}],['Try to preserve both relationships and avoid explicit commitments.',{door:2,pressure:1}]],advice:'Neutrality between one’s own alliance and its rival is not balance. It is uncertainty sold to both sides.'},
55:{advisor:'alexandra',body:['On New Year’s Eve the empire appears stronger than at any point since the Japanese war. Industrial output is high, the army is rebuilding, and the dynasty has just celebrated three centuries. Yet Europe is divided into armed blocs and Balkan crises arrive faster than settlements.','Alexandra urges confidence in the Crown. Ministers urge caution abroad. Generals urge preparation. The final peacetime year begins with all three sounding reasonable.'],quote:'“Promise me only that you will not let ministers frighten you into betraying yourself.”',speaker:'Alexandra Feodorovna',choices:[['Make preservation of peace the explicit priority of 1914 and instruct ministers to avoid automatic Balkan commitments.',{pressure:-2,legitimacy:1,flags:['peacePriority']}],['Continue current policy without a new declaration.',{economy:1}],['Make military readiness the priority even if foreign capitals read the buildup politically.',{military:2,economy:-1,pressure:1}],['Begin a private correspondence with Wilhelm aimed at preventing a German-Russian war under any circumstances.',{flags:['germanophile','willyNicky'],veil:1,pressure:-1}]],advice:'Nicky, strength is supposed to make peace easier. Do not let men convince you that strength is wasted unless it is demonstrated.'},
56:{advisor:'sazonov',body:['Archduke Franz Ferdinand and Sophie are assassinated in Sarajevo by Gavrilo Princip, a Bosnian Serb linked to nationalist networks with connections reaching into Serbia. Vienna believes the murder offers a chance to settle the Serbian question permanently.','Russia must decide immediately whether Serbia is a client whose conduct can be restrained, or a test of Russian status no matter what Belgrade has done.'],quote:'“Serbia is not innocent. That does not mean Austria may erase it.”',speaker:'Sergei Sazonov',choices:[['Tell Belgrade to cooperate fully with an investigation and privately tell Vienna Russia will accept severe but limited demands.',{pressure:-2,legitimacy:1,flags:['julyRestraint']}],['Warn Vienna that Serbia’s sovereignty cannot be destroyed, while demanding Serbian arrests of implicated officers.',{empire:1,pressure:0,flags:['serbiaWarning']}],['Assure Serbia that Russia will not permit Austrian coercion beyond normal diplomacy.',{empire:2,pressure:2,flags:['blankChequeSerbia']}],['Ask Berlin to join Russia in imposing a joint investigation and freeze unilateral Austrian action.',{pressure:-1,flags:['germanophile']}]],advice:'The assassination is a crime. The danger is every capital deciding the crime has answered political questions that existed before it.'},
57:{advisor:'sazonov',body:['Berlin gives Vienna what becomes known as the blank cheque: German support even if Austrian action against Serbia risks conflict with Russia. Russian diplomats learn enough of the firmness to understand that Vienna may be less interested in compromise than usual.','The correct response could be counter-pressure, mediation, or a deliberate effort to separate Berlin from Vienna before the ultimatum arrives.'],quote:'“Germany has insured Austria against caution.”',speaker:'Sergei Sazonov',choices:[['Send Berlin a direct proposal for four-power mediation before Vienna issues demands.',{pressure:-2,legitimacy:1}],['Quietly warn Germany that destruction of Serbia will trigger Russian military measures.',{pressure:1,military:1}],['Tell Serbia to accept any demand consistent with formal sovereignty and prepare to pressure it publicly.',{pressure:-1,empire:-1,flags:['julyRestraint']}],['Use the crisis to finalize a Russian-German bargain: no Russian support for Serbia in exchange for German restraint on Austria.',{pressure:-2,flags:['germanophile','serbiaAbandoned']}]],advice:'A blank cheque is dangerous because it makes the recipient spend someone else’s risk.'},
58:{advisor:'sazonov',body:['Serbian diplomats ask what Russia means by support. They need to know how far Belgrade can concede without being abandoned and how far it can resist without standing alone.','This is the moment when ambiguity can still be converted into discipline. Once mobilization begins, Serbian assumptions may matter as much as Russian intentions.'],quote:'“If Serbia believes we will fight for every comma, she will negotiate every comma accordingly.”',speaker:'Sergei Sazonov',choices:[['Tell Serbia explicitly to accept intrusive investigation short of Austrian police exercising sovereign power inside Serbia.',{pressure:-1,legitimacy:1,flags:['serbiaLimited']}],['Promise diplomatic and financial support but no military guarantee.',{empire:1,pressure:0}],['Promise that Russia will not allow Serbia to be humiliated or partitioned.',{empire:2,pressure:2,flags:['serbiaEntangled']}],['Tell Serbia Russia will not fight Austria over this crisis and advise complete acceptance.',{empire:-2,pressure:-2,flags:['serbiaAbandoned']}]],advice:'An ally should know the line before he reaches it. Otherwise he discovers the line by dragging you across it.'},
59:{advisor:'sazonov',body:['Austria delivers its ultimatum to Serbia with a forty-eight-hour deadline. Several demands are intentionally difficult, especially Austrian participation in investigations on Serbian soil. European diplomats immediately recognize that the document may have been written to be rejected.','Belgrade can accept most of it. Russia can urge full acceptance, support a reservation, or treat the ultimatum itself as the act that ends diplomacy.'],quote:'“This is not a note. It is an instrument designed to produce a refusal.”',speaker:'Sergei Sazonov',choices:[['Urge Serbia to accept every point except direct Austrian exercise of police power, and offer international supervision of that point.',{pressure:-2,legitimacy:2}],['Demand that Austria extend the deadline and submit disputed clauses to a conference.',{pressure:-1,empire:1}],['Tell Serbia the ultimatum is intolerable and Russia will support rejection.',{empire:2,pressure:3,flags:['serbiaEntangled']}],['Accept the ultimatum as Austria’s sphere problem and remain outside the dispute.',{pressure:-3,empire:-2,flags:['serbiaAbandoned']}]],advice:'The fact that Vienna wants refusal does not require us to provide it.'},
60:{advisor:'sazonov',body:['Serbia accepts most Austrian demands but reserves on the most intrusive provisions. Vienna breaks relations anyway. European chancelleries debate whether the Serbian reply is enough to justify halting military action.','Russia can publish the reply, internationalize it, or move directly toward military precautions.'],quote:'“Belgrade has given us a document with which to isolate Vienna—if we use the document before the army uses the railways.”',speaker:'Sergei Sazonov',choices:[['Publish Serbia’s reply and demand that Britain, France, Germany and Italy jointly declare it a basis for negotiation.',{legitimacy:3,pressure:-2}],['Offer direct Russian-Austrian talks while beginning only nonpublic military precautions.',{military:1,pressure:0}],['Authorize preliminary mobilization measures in the four southern military districts.',{military:2,pressure:2}],['Tell Berlin Russia will remain neutral if Austria accepts the Serbian reply and stops at Belgrade.',{pressure:-1,flags:['germanophile']}]],advice:'There is still a diplomatic advantage to being visibly the side asking what Austria actually requires. Do not surrender it casually.'},
61:{advisor:'nicholas',body:['Austria declares war on Serbia and shells Belgrade. The Russian General Staff argues that partial mobilization against Austria is operationally awkward because plans, depots and rail allocations were built around a broader conflict.','The military difficulty is genuine. But this is also the moment when a technical inconvenience can become a political ultimatum to the sovereign.'],quote:'“Majesty, partial mobilization is possible. It is simply not the plan we preferred to write.”',speaker:'General Danilov',choices:[['Order the partial plan and accept temporary military inefficiency to preserve diplomatic space.',{military:-1,pressure:-1,flags:['partialMobilization']}],['Order only readiness measures, fortress reinforcement and recall of reservists without formal mobilization.',{military:1,pressure:0,flags:['preparedOnly']}],['Order general mobilization on the ground that Germany may enter immediately.',{military:2,pressure:4,blood:2,flags:['generalMobilization']}],['No mobilization while direct Russian-Austrian talks remain open.',{legitimacy:1,military:-1,pressure:-2,flags:['noMobilization']}]],advice:'The plan is not sacred. If it cannot execute the policy you choose, the failure belongs to the plan.'},
62:{advisor:'sazonov',body:['You and Wilhelm exchange personal telegrams. Both insist they want peace. Wilhelm says he is mediating in Vienna; you ask him to restrain Austria. Beneath the cousinly language, both general staffs are watching the same hours disappear.','Personal diplomacy can still clarify intent, but it can also become a substitute for binding instructions to governments and armies.'],quote:'“Dear Nicky, I am exerting my utmost influence to induce the Austrians to deal straightly.”',speaker:'Kaiser Wilhelm II',choices:[['Ask Wilhelm for a concrete Austrian halt-at-Belgrade proposal and promise no Russian general mobilization while it is active.',{pressure:-2,flags:['willyNicky','haltBelgrade']}],['Tell Wilhelm plainly that Russian general mobilization will follow any Austrian advance beyond limited punitive action.',{pressure:1,military:1}],['Offer a cousin-to-cousin agreement that Germany restrains Austria while Russia restrains Serbia and France.',{pressure:-2,flags:['germanophile','willyNicky']}],['Keep the exchange personal and let Sazonov and the General Staff proceed independently.',{door:2,pressure:1}]],advice:'Personal trust is useful only if it becomes an order someone else must obey.'},
63:{advisor:'nicholas',body:['The General Staff reports that preparatory measures are beginning to interfere with civilian rail traffic, reserve movements and ordinary commerce. What diplomats call “not mobilization” is starting to look operationally similar to mobilization in several districts.','The bureaucracy has discovered a gray zone between peace and war, and everyone is using it for a different purpose.'],quote:'“We are trying to be militarily ready without appearing politically committed. The railways cannot read intentions.”',speaker:'General Yanushkevich',choices:[['Freeze further military measures for twenty-four hours and audit exactly what has already been ordered.',{pressure:-1,military:-1,door:-1}],['Continue readiness measures but prohibit movements that cross district boundaries.',{military:1,pressure:0}],['Let the General Staff complete preparatory deployment so mobilization, if ordered, will not lose time.',{military:2,pressure:2,flags:['armyAutonomy']}],['Transfer control of military rail priorities to a joint civilian-military committee for the crisis.',{reform:1,military:1,door:-1}]],advice:'The dangerous phrase is “preparatory measure.” Every department uses it to mean something different and then insists nothing irreversible has happened.'},
64:{advisor:'nicholas',body:['Red mobilization forms and sealed orders are ready. District commanders want clarity because contradictory instructions now risk producing disorder worse than either mobilization or peace.','The issue is no longer abstract strategy. It is whether the Russian state can issue one coherent command before foreign governments interpret the confusion for it.'],quote:'“Majesty, uncertainty is now itself an order, and not a good one.”',speaker:'General Yanushkevich',choices:[['Issue one written directive canceling all mobilization orders not personally countersigned by the Council chairman and War Minister.',{door:-2,pressure:-1,autocracy:1}],['Confirm partial mobilization against Austria and forbid expansion without another imperial order.',{military:1,pressure:0,flags:['partialMobilization']}],['Sign general mobilization and end the ambiguity.',{military:2,pressure:4,blood:2,flags:['generalMobilization']}],['Delegate final mobilization execution to the General Staff once diplomatic triggers are met.',{military:2,autocracy:-1,flags:['armyAutonomy']}]],advice:'A state can survive a bad order more easily than three incompatible good intentions.'},
65:{advisor:'alexandra',body:['Alexandra argues that Germany will not attack if you remain firm and that ministers are allowing fear to govern you. At the same time she distrusts Sazonov and the Duma, while Rasputin—if still trusted—has sent warnings against war.','Family counsel, spiritual counsel and state counsel now point in different directions for different reasons.'],quote:'“Do not let them make you a coward in one direction merely because they call courage the other.”',speaker:'Alexandra Feodorovna',choices:[['Tell Alexandra the decision must be made through ministers and military facts, not court pressure.',{door:-2,legitimacy:1,veil:-1}],['Follow Rasputin’s warning and order every measure aimed at general war suspended.',{pressure:-2,veil:2,flags:['rasputinPeace']}],['Accept Alexandra’s argument that firmness will deter Germany and maintain mobilization preparations.',{autocracy:1,pressure:2}],['Bring Alexandra, Sazonov and the War Minister into the same room and force the contradictions into the open.',{door:-1,pressure:-1}]],advice:'Nicky, whatever you choose, choose it because you believe it—not because the last frightened person in the room sounded certain.'},
66:{advisor:'nicholas',body:['You have ordered and counterordered military measures in rapid succession. The General Staff warns that reversing again will produce confusion in stations, depots and units already moving.','This is the constitutional crisis hidden inside the military one: whether the sovereign can still change policy after machinery begins executing it.'],quote:'“Of course you may countermand it, Majesty. I am telling you the cost, not denying the authority.”',speaker:'Grand Duke Nicholas Nikolaevich',choices:[['Countermand general mobilization and accept the military disruption.',{legitimacy:2,military:-2,pressure:-2,flags:['mobilizationReversed','peace1914']}],['Stabilize at partial mobilization and order the General Staff to make it work.',{military:0,pressure:-1,flags:['partialMobilization']}],['Confirm general mobilization rather than risk organizational collapse.',{military:2,pressure:3,blood:2,flags:['warMachine']}],['Suspend execution for six hours while you and Wilhelm seek a simultaneous stand-down.',{pressure:-2,military:-1,flags:['willyNicky']}]],advice:'Authority that cannot reverse a machine is ceremonial. But a machine reversed every hour is not command either.'},
67:{advisor:'sazonov',body:['Germany presents an ultimatum demanding Russia halt military measures. Berlin argues that Russian mobilization threatens German survival under its own war plans. Sazonov points out that accepting the demand unilaterally may expose Russia to Austria while German preparations continue.','The ultimatum transforms a Balkan dispute into a direct German-Russian confrontation.'],quote:'“Berlin is asking us to prove peaceful intent by becoming strategically helpless first.”',speaker:'Sergei Sazonov',choices:[['Offer simultaneous Russian-German suspension of mobilization under immediate diplomatic verification.',{pressure:-2,legitimacy:2}],['Stop Russian measures if Germany guarantees Austria will halt operations beyond Serbia.',{pressure:-1,empire:-1}],['Reject the ultimatum but continue proposing mediation.',{legitimacy:1,pressure:2}],['Reject it as incompatible with Russian sovereignty and prepare for war.',{autocracy:2,blood:2,pressure:4,flags:['war1914']}]],advice:'The ultimatum is designed around distrust. Our answer should either break that logic or acknowledge that we are already at war.'},
68:{advisor:'sazonov',body:['German embassy staff burn papers. Crowds gather outside. Rumors spread faster than official bulletins: invasion, betrayal, mobilization, victory, assassination.','The government must decide how to speak to the public before the public constructs its own version of the war.'],quote:'“The first casualty may be truth, but ministries need not shoot it personally.”',speaker:'A Foreign Ministry press officer',choices:[['Publish the diplomatic correspondence and explain exactly which proposals failed.',{legitimacy:3,reform:1}],['Issue a restrained proclamation calling for calm while negotiations continue.',{legitimacy:1,pressure:-1}],['Frame the crisis as a German attack on Slavic Russia and call the nation to unity.',{autocracy:1,empire:2,blood:1,pressure:2}],['Suppress hostile newspapers and arrest demonstrators around foreign embassies.',{autocracy:2,blood:1,legitimacy:-1}]],advice:'If war comes, the country will remember whether it was told what happened or merely what to feel.'},
69:{advisor:'sazonov',body:['One final exchange remains possible among Berlin, Vienna, Petersburg and London. Every proposal is now entangled with mobilization status, alliance commitments and fear of losing hours.','A diplomatic compromise may cost prestige and military position. Refusing one may cost Europe.'],quote:'“There is no elegant exit left. There may still be an exit.”',speaker:'Sergei Sazonov',choices:[['Accept a conference, halt further Russian movements and compel Serbia to accept international supervision.',{legitimacy:3,empire:-1,pressure:-3,flags:['peace1914']}],['Offer simultaneous Austrian halt and Russian partial demobilization under German and British guarantees.',{legitimacy:2,pressure:-2,flags:['conditionalPeace']}],['Refuse further delay; Russia cannot retreat under German ultimatum.',{autocracy:2,blood:3,pressure:4,flags:['war1914']}],['Ask Wilhelm directly for a bilateral stand-down even if France and Austria object.',{pressure:-2,flags:['willyNicky','germanophile']}]],advice:'At this stage peace will look humiliating to someone. That is cheaper than making every cemetery in Europe impartial.'},
70:{advisor:'rasputin',body:['The final orders are waiting. Germany and Russia are at the edge of formal war. The palace is quiet enough that ordinary sounds—the clock, footsteps, distant bells—seem indecently clear.','Nine years of decisions have built the Russia that will now meet this hour: constitutional or autocratic, prosperous or brittle, disciplined or merely obedient. There is no remaining committee to hide behind.'],quote:'“If Russia goes to war, there will be no Tsar.”',speaker:'Grigori Rasputin',choices:[['Stop it. Accept the diplomatic cost, cancel offensive measures and force the crisis back into negotiation.',{legitimacy:3,autocracy:-2,blood:-2,pressure:-4,flags:['peace1914']}],['Enter the war with limited aims, parliamentary finance and civilian control of the cabinet.',{military:2,legitimacy:1,blood:2,flags:['war1914','limitedWar']}],['Enter general war and mobilize the empire for victory without constitutional restraint.',{autocracy:3,military:2,blood:4,flags:['war1914','totalWar']}],['Dissolve the Duma, vest emergency authority in the high command and tell Rasputin that God will judge the rest.',{veil:4,autocracy:3,military:3,blood:4,flags:['war1914','eschaton','armyRule']}]],advice:'“Let death seize upon them, and let them go down quick into hell.” You ask me who I mean. I do not say.'}
};

// Install bespoke copy and choices over every generic fallback. Branch-specific variants may still override these at runtime.
Object.entries(OATR_EVENT_DETAIL).forEach(([id, event]) => {
  OATR_KEY_TEXT[id] = { body: event.body, quote: event.quote, speaker: event.speaker };
  OATR_SPECIAL_CHOICES[id] = event.choices;
});

function oatrEventAdvisor(questionId) {
  const event = OATR_EVENT_DETAIL[questionId];
  return event ? event.advisor : null;
}

function oatrEventAdvice(questionId) {
  return OATR_EVENT_DETAIL[questionId]?.advice || null;
}
